-- 0052: بندا الأثاث غير الطبي والتجهيزات الطبية لمجموعة مركز نموذج المسار الرابع (يسعّرهما المقاول)، وإضافتهما للنطاق وجدول مركز النعيم. قابل لإعادة التشغيل.
insert into public.ls_items (code, grp, title, descr, unit, sort, div_code) values
 ('LS-93', 'مركز نموذج المسار الرابع', 'الأثاث غير الطبي', $q$توريد وتركيب الأثاث غير الطبي لكامل المركز حسب المخططات وجداول الأثاث، يحسب المقاول أعداده من المخططات لكل فراغ، ويشمل على سبيل المثال لا الحصر: منطقة الاستقبال والانتظار: مقاعد انتظار معدنية متصلة (2–4 مقاعد) بتنجيد فينيل طبي مقاوم للبكتيريا وسهل التنظيف بمساند أيدٍ، مع مقاعد مخصصة لكبار السن وأماكن لكراسي ذوي الإعاقة، وطاولات جانبية، وكرسيا موظفي الاستقبال؛ كل عيادة: مكتب طبيب بأدراج، وكرسي طبيب طبي دوّار بمساند، وكرسيان للمراجع والمرافق، وخزانة علوية أو جانبية، وسلة نفايات؛ المكاتب الإدارية: مكتب وكرسي لكل موظف، وكراسي ضيوف، وخزائن ملفات بأقفال؛ غرفة الاجتماعات: طاولة اجتماعات بكراسيها؛ استراحة الموظفين: طاولة طعام بكراسيها وكنب جلوس؛ مناطق التمريض والعلامات الحيوية وسحب الدم: كراسي ممرض بعجلات وكراسي مراجعين؛ المخازن وغرف الخدمات: أرفف ستانلس ستيل أو معدنية مدهونة بودرة قابلة للتعديل بارتفاع لا يقل عن 20 سم عن الأرض؛ وخزائن الملابس (لوكرز) للموظفين حيث وردت؛ جميع الأثاث بمواد مقاومة للاشتعال وسهلة التنظيف والتعقيم ومتوافقة مع متطلبات مكافحة العدوى، وكراسي العمل بضمان لا يقل عن 5 سنوات وباقي الأثاث سنتان، مع تقديم كتالوجات وعينات الألوان والخامات للاعتماد قبل التوريد، والتجميع والتثبيت والتوزيع في المواقع وإزالة التغليف. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 916, '12'),
 ('LS-94', 'مركز نموذج المسار الرابع', 'التجهيزات الطبية', $q$توريد وتركيب وتشغيل التجهيزات الطبية لمركز رعاية صحية أولية (طب أسرة) لكامل العيادات والأقسام الواردة في المخططات، يحسب المقاول أعدادها من المخططات لكل فراغ، ويشمل على سبيل المثال لا الحصر: كل عيادة: سرير فحص كهربائي أو هيدروليكي بدرجة سلم، وجهاز ضغط رقمي جداري أو على حامل، ومجموعة فحص تشخيصي جدارية (منظار أذن وعين بمقابض قابلة للشحن)، وكشاف فحص، وميزان وأداة قياس طول، وسماعة طبية، وستارة الفحص (ضمن بند الستائر)؛ العلامات الحيوية: جهاز علامات حيوية (ضغط، نبض، حرارة، تشبع أكسجين)، وميزان رقمي للبالغين بقياس طول، وميزان أطفال رضع ولوحة قياس طول؛ الطوارئ والضماد: عربة إنعاش (Crash Cart) مجهزة، وجهاز صدمات خارجي آلي (AED) أو مزيل رجفان بشاشة، وجهاز شفط متنقل، وجهاز تخطيط قلب 12 قناة، وجهاز بخار (Nebulizer)، وأسطوانة أكسجين متنقلة على عربة بمنظمها، وسرير أو نقالة طوارئ بحواجز، وعربة ضماد ستانلس، وحامل محاليل، وكرسي متحرك؛ سحب الدم والتطعيم: كرسي سحب دم بمساند ذراع، وثلاجة لقاحات طبية بمسجل حرارة ومنبه وفق متطلبات سلسلة التبريد، وثلاجة أدوية طبية، وجهاز قياس السكر؛ التعقيم: جهاز تعقيم بالبخار (Autoclave) منضدي بحجم مناسب، وجهاز تغليف الأدوات (Sealer)، وأرفف وعربات نقل الأدوات النظيفة والمتسخة؛ وما يرد في المخططات أو قائمة تجهيزات الأقسام (مثل عيادة الأسنان أو المختبر إن وُجدت) بالتجهيزات المعيارية لها؛ جميع الأجهزة جديدة ومسجلة لدى الهيئة العامة للغذاء والدواء (MDMA) من وكيل معتمد في المملكة، مع البيانات الفنية والكتالوجات للاعتماد من قسم التجهيزات الطبية والصيانة الطبية قبل التوريد، والتركيب والتشغيل والمعايرة وشهادات المعايرة واختبارات السلامة الكهربائية، وتدريب المستخدمين وفنيي الصيانة الطبية، وكتيبات التشغيل والصيانة، وضمان لا يقل عن سنتين للأجهزة مع الصيانة الوقائية خلال الضمان وتوفر قطع الغيار لمدة لا تقل عن 7 سنوات، وتسجيل الأجهزة في سجل الأصول قبل الاستلام. وكل ما يلزم لإنجاز العمل كاملاً جاهزاً للتشغيل حسب المخططات والمواصفات ولو لم يُذكر صراحة.$q$, 'مقطوعية', 917, '11')
on conflict (code) do nothing;
update public.ls_templates set codes = codes || array['LS-93','LS-94']::text[], updated_at = now() where name = 'مركز نموذج المسار الرابع (إنشاء كامل)' and not ('LS-93' = any(codes));
do $$ declare b uuid; begin
  if exists (select 1 from public.seed_marks where key = 'boq_naeem_ls93_94') then return; end if;
  select id into b from public.boqs where name = 'مقطوعية — نموذج المسار الرابع' order by created_at limit 1;
  if b is null then return; end if;
  insert into public.boq_lines (boq_id, kind, title, descr, unit, qty, div_code, sort)
    select b, 'free', i.title, i.descr, i.unit, 1, i.div_code, 57 + (i.code = 'LS-94')::int from public.ls_items i
    where i.code in ('LS-93','LS-94') and not exists (select 1 from public.boq_lines l where l.boq_id = b and l.title = i.title and l.div_code = i.div_code);
  insert into public.seed_marks (key) values ('boq_naeem_ls93_94');
end $$;
